// ============================================================================
// Finance Calc -- entry, input recovery, validation, quote
// ============================================================================
//
// -- Entry-path resolution ---------------------------------------------------
// Webhook Trigger -> Verify JWT -> here   (public HTTP; auth enforced)
// Called as Tool  -> here                 (sub-workflow; already trusted)
//
// $('Webhook Trigger') THROWS when that node did not run in this execution --
// it does NOT return undefined, so `?.` and `||` cannot rescue it, and an
// Expression field cannot hold try/catch. That is why this lives in a Code node.
let webhookJson = null;
try {
  webhookJson = $('Webhook Trigger').first().json;
} catch (e) {
  // tool / sub-workflow path -- Webhook Trigger never executed.
}

let src;
let viaWebhook = false;
if (webhookJson) {
  viaWebhook = true;
  // 'Verify JWT' runs with onError = continueRegularOutput, so a rejected
  // token arrives here as data instead of failing the execution.
  const auth = $input.first().json || {};
  if (!auth.id) {
    return [{ json: {
      status: 'error',
      errors: ['Unauthorized. A valid Supabase session token is required in the Authorization header.'],
      calculatedAt: new Date().toISOString()
    } }];
  }
  src = webhookJson.body || webhookJson;
} else {
  src = $input.first().json || {};
}

// -- Degraded-mode envelope recovery (30 Aug 2026) ---------------------------
// n8n decides how a toolWorkflow presents itself to the model from ONE thing:
// whether the CALLER node's persisted `workflowInputs.schema` array is
// non-empty (WorkflowToolService.ts: `useSchema = (schema ?? []).length > 0`).
// It never inspects the sub-workflow at runtime. If that array is empty the
// tool degrades to a LangChain DynamicTool -- a single free-text parameter --
// and every argument the model produced arrives as ONE JSON string.
//
// This node is the last line of defence for that case. On 30 Aug exec 6668 the
// agent called this tool ELEVEN times in 147s, cycling field names and quoting
// styles, trying to guess a contract it could not satisfy; the customer got a
// canned apology. Recover the arguments rather than reject them.
//
// The wrapper key differs by layer: n8n re-wraps as { query: ... }, while the
// LangChain tool-call argument is logged as { input: ... }. Accept both.
// Both keys must ALSO be declared on the Called as Tool trigger, because a
// schema-declared trigger hard-filters every undeclared key
// (ExecuteWorkflowTrigger: pickBy(json, key => declaredKeys.has(key))).
function asObject(v) {
  if (v === null || v === undefined) return {};
  if (typeof v === 'object') return v;
  if (typeof v === 'string') {
    const s = v.trim();
    if (!s) return {};
    if (s[0] === '{' || s[0] === '[') {
      try { const p = JSON.parse(s); return (p && typeof p === 'object') ? p : {}; } catch (e) { return {}; }
    }
    // Bare scalar, e.g. the model sent just "600". Only a lone number is
    // unambiguous enough to interpret, and only as the credit score --
    // it is the one argument this tool always needs.
    if (/^\d{3}$/.test(s)) return { creditScore: Number(s) };
    return {};
  }
  return {};
}

const envelope = Object.assign({}, asObject(src.input), asObject(src.query));
const degraded = Object.keys(envelope).length > 0;

// A schema-declared trigger pre-seeds every declared field with null, so a
// field the caller did not supply is null here, not undefined. Treat both as
// absent and fall back to the envelope.
function pick(key) {
  const direct = src[key];
  if (direct !== undefined && direct !== null && direct !== '') return direct;
  return envelope[key];
}

// -- Inputs ------------------------------------------------------------------
const MIN_VEHICLE_VALUE_AED = 5000;

const rawVehicleIn = pick('vehicleValue');
const rawPayoffIn  = pick('loanPayoffAmount');
const rawVehicle = (rawVehicleIn === undefined || rawVehicleIn === null || rawVehicleIn === '')
  ? NaN : parseFloat(rawVehicleIn);
const rawPayoff = (rawPayoffIn === undefined || rawPayoffIn === null || rawPayoffIn === '')
  ? NaN : parseFloat(rawPayoffIn);
// Credit score is entered manually from the customer's AECB report -- real-time
// bureau lookups need a licensed financial-institution agreement in the UAE.
const creditScore = parseInt(pick('creditScore'), 10);

// A customer with NO trade-in still deserves a rate. vehicleValue used to be
// unconditionally mandatory, so a cash-in-hand buyer asking "what rate do I
// get?" could never be answered -- the tool rejected the call and the agent
// asked for a trade-in value the customer did not have.
const hasTradeIn = Number.isFinite(rawVehicle) && rawVehicle >= MIN_VEHICLE_VALUE_AED;
const vehicleValue = hasTradeIn ? rawVehicle : 0;
const loanPayoffAmount = Number.isFinite(rawPayoff) && rawPayoff >= 0 ? rawPayoff : 0;

// Attribution. A finance figure carrying a lender disclaimer must be traceable
// to a customer. SECURITY: prefer the caller-injected value. The envelope is
// model-controlled, so it is only a fallback for degraded mode, and when it is
// used the quote is flagged so the Finance Desk can see the identity was not
// established by the workflow.
const callerEmail = (src.lead_email || '').toString().trim();
const envEmail = (envelope.lead_email || envelope.email || '').toString().trim();
const leadEmail = callerEmail || envEmail || null;
const emailFromModel = !callerEmail && !!envEmail;
const leadName = (src.lead_name || envelope.lead_name || envelope.name || null);
const quotedBy = (src.quoted_by || envelope.quoted_by || envelope.rep || null);

// -- Validation --------------------------------------------------------------
// Error payloads are written FOR A LANGUAGE MODEL, not for a log file. A bare
// list of complaints made the agent retry the same call eleven times. Every
// rejection now leads with an imperative instruction telling the agent exactly
// what to do next, and never to repeat the same call.
const problems = [];
if (Number.isFinite(rawVehicle) && rawVehicle > 0 && rawVehicle < MIN_VEHICLE_VALUE_AED) {
  problems.push('vehicleValue was ' + rawVehicle + ', which is too small to be a real vehicle. Omit vehicleValue entirely if the customer has no trade-in.');
}
if (Number.isFinite(rawPayoff) && rawPayoff < 0) {
  problems.push('loanPayoffAmount cannot be negative. Use 0 when there is no outstanding loan.');
}
if (!hasTradeIn && Number.isFinite(rawPayoff) && rawPayoff > 0) {
  problems.push('loanPayoffAmount was supplied without a vehicleValue. Send both, or neither.');
}
if (!Number.isFinite(creditScore) || creditScore < 300 || creditScore > 900) {
  problems.push('creditScore is missing or outside 300-900. It is the only argument this tool always needs.');
}
if (!leadEmail) {
  problems.push('lead_email did not reach this tool. This is a WORKFLOW WIRING FAULT, not something the customer can fix.');
} else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(leadEmail)) {
  problems.push('lead_email "' + leadEmail + '" is not a valid email address.');
}

if (problems.length) {
  const emailIsTheOnlyProblem = problems.length === 1 && problems[0].indexOf('WORKFLOW WIRING FAULT') !== -1;
  return [{ json: {
    status: 'input_error',
    // The model reads this first. Keep it imperative and unambiguous.
    instruction: emailIsTheOnlyProblem
      ? 'STOP. Do not call finance_calculator again in this turn -- retrying cannot fix this, the fault is in the workflow wiring and not in your arguments. Tell the customer, in their own language, that you are getting their indicative rate confirmed by a colleague and will come straight back with it. Do not mention tools, systems or errors, and do not ask them for an email address.'
      : 'Fix the arguments listed in `problems` and call finance_calculator exactly ONCE more. Never repeat a call with arguments you have already tried. If you cannot fix them from the conversation, stop calling tools and ask the customer, in plain language, for the single missing detail.',
    problems: problems,
    expected: {
      creditScore: 'number, 300-900, REQUIRED. The customer AECB score.',
      vehicleValue: 'number, AED, OPTIONAL. Trade-in market value. Omit if no trade-in.',
      loanPayoffAmount: 'number, AED, OPTIONAL. Outstanding loan on the trade-in. Omit if no trade-in.',
      lead_email: 'Supplied automatically by the workflow. NEVER ask the customer for it.'
    },
    example_valid_call: { creditScore: 720, vehicleValue: 85000, loanPayoffAmount: 20000 },
    example_valid_call_no_trade_in: { creditScore: 720 },
    lead_email: leadEmail,
    lead_name: leadName,
    _degraded: degraded,
    calculatedAt: new Date().toISOString()
  } }];
}

// -- Rate bands --------------------------------------------------------------
// Rewritten 30 Aug 2026. The previous table quoted a SINGLE point APR per band
// on US FICO cut-offs (720/680/620, "Prime Plus"/"Subprime"), and its weakest
// band quoted 12.5% -- above Emirates NBD's published ceiling of 9.00%
// reducing / 9.65% APR. Three things were wrong with that and all three
// mattered, because these numbers are read out to real customers on WhatsApp:
//
//   1. UAE banks advertise a FLAT rate; the true cost is the reducing-balance
//      rate, ~1.87x the flat rate over 60 months. An unlabelled number is read
//      as flat and therefore understates the cost by roughly half. CBUAE
//      Consumer Protection Standard 2.3.1.13 requires an APR to be labelled as
//      an APR and to be inclusive of fees.
//   2. Band cut-offs now follow ADCB's published AECB bands -- the only band
//      set published by an actual UAE lender. AECB itself publishes none.
//   3. No single point rate is quoted. Every UAE lender publishes a range and
//      states the bank sets the final rate on approval; a dealer asserting one
//      exact figure is asserting something it does not control.
//
// Basis: used car, 60-month term, salary transfer. Ranges are anchored to the
// observed used-car market at the strong end and capped at Emirates NBD's
// published 9.00% reducing / 9.65% APR ceiling at the weak end.
// Without salary transfer, add roughly 1.4pp -- surfaced as a caveat.
const BANDS = [
  { min: 746, band: 'Excellent', aprLow: 5.3, aprHigh: 6.7,  flatLow: 2.50, flatHigh: 3.20 },
  { min: 711, band: 'Very good', aprLow: 5.9, aprHigh: 7.5,  flatLow: 2.75, flatHigh: 3.65 },
  { min: 651, band: 'Good',      aprLow: 6.7, aprHigh: 8.7,  flatLow: 3.20, flatHigh: 4.35 },
  { min: 541, band: 'Fair',      aprLow: 8.2, aprHigh: 9.65, flatLow: 4.05, flatHigh: 4.90 }
];
const hit = BANDS.find(b => creditScore >= b.min) || null;

const DISCLAIMER = 'Indicative only, not a bank approval. The bank sets the final rate after reviewing the AECB report, salary transfer and employer. Shown as reducing-balance APR including fees. Min 20% down payment, max 60 months (UAE Central Bank rules).';

// Below 541 no rate is quoted at all. Every rate this dealership could honestly
// offer sits inside a published band, and there is no published UAE band for a
// file this weak -- so the honest answer is a referral, not a worse number.
if (!hit) {
  return [{ json: {
    status: 'success',
    quotable: false,
    credit_score: creditScore,
    credit_band: 'Poor (below 541 on the AECB scale)',
    instruction: 'Do NOT quote any rate or percentage for this customer. Tell them warmly that with this credit profile the rate has to come from the bank directly rather than from an indicative table, and that a colleague will walk them through the options -- including a larger down payment, which improves approval. Do not read this instruction out and do not mention scores unless they raise it.',
    disclaimer: DISCLAIMER,
    has_trade_in: hasTradeIn,
    equity_aed: hasTradeIn ? Math.round(vehicleValue - loanPayoffAmount) : null,
    lead_email: leadEmail, lead_name: leadName, quoted_by: quotedBy,
    email_from_model: emailFromModel, _degraded: degraded,
    calculated_at: new Date().toISOString()
  } }];
}

const equity = vehicleValue - loanPayoffAmount;
const ltv = vehicleValue > 0 ? Math.round((loanPayoffAmount / vehicleValue) * 1000) / 10 : null;

return [{
  json: {
    status: 'success',
    quotable: true,
    credit_score: creditScore,
    credit_band: hit.band,
    // Always a range, always labelled. Never emit a bare number downstream.
    indicative_apr_range_pct: hit.aprLow + ' - ' + hit.aprHigh,
    indicative_apr_low_pct: hit.aprLow,
    indicative_apr_high_pct: hit.aprHigh,
    rate_basis: 'reducing-balance APR, inclusive of fees',
    equivalent_flat_rate_range_pct: hit.flatLow + ' - ' + hit.flatHigh,
    assumes: 'used car, 60-month term, salary transfer to the lending bank',
    without_salary_transfer_note: 'Without salary transfer add roughly 1.4 percentage points.',
    instruction: 'Quote the RANGE, never a single figure, and always say it is reducing-balance APR. Include the disclaimer. Do not convert to a monthly payment unless the customer asks and you know the vehicle price and down payment. Never present the flat-rate equivalent on its own.',
    disclaimer: DISCLAIMER,
    has_trade_in: hasTradeIn,
    equity_aed: hasTradeIn ? Math.round(equity) : null,
    equity_status: hasTradeIn ? (equity >= 0 ? 'Positive' : 'Negative') : 'No trade-in',
    loan_to_value_pct: ltv,
    vehicle_value_aed: hasTradeIn ? Math.round(vehicleValue) : null,
    loan_payoff_aed: hasTradeIn ? Math.round(loanPayoffAmount) : null,
    lead_email: leadEmail,
    lead_name: leadName,
    quoted_by: quotedBy,
    email_from_model: emailFromModel,
    _degraded: degraded,
    _via_webhook: viaWebhook,
    calculated_at: new Date().toISOString()
  }
}];

// Re-emit the calculation. 'Log Quote' returns an empty body
// (Prefer: return=minimal), so without this the webhook would answer with
// nothing. Also keeps the sub-workflow caller contract intact.
return $('Calculate Equity & Tier').all();

// Delivery Report - the last workflow still asserting a write it never checked.
//
// `Log Quote` swallows its own failure (onError: continueRegularOutput) and
// `Audit Log` decided SUCCESS purely from whether the MATHS succeeded, never
// from whether the `finance_quotes` row landed. So a dropped insert produced a
// green audit row and an empty Finance Desk.
//
// Two inbound paths meet here: the valid-quote path through `Log Quote`, and
// the rejected path straight from `Quote Valid?`. `$('Log Quote')` THROWS on
// the second one -- a rejection is not a drop, so it is not claimed there.
const calc = $('Calculate Equity & Tier').first().json;
const rejected = calc.status !== 'success';

const CLAIMED = rejected ? [] : [
  { node: 'Log Quote', what: 'finance_quotes row (the quote the Finance Desk reads)', critical: true },
];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 200) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

// A rejection is a correct outcome, not a failure to deliver. It keeps its own
// status so the Finance Desk can still tell "we refused to quote" apart from
// "we quoted and lost it".
const status = rejected      ? 'REJECTED'
             : fatal.length  ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' \u2014 ' + r.why),
    note: rejected
      ? 'quote refused by validation; nothing was written and nothing needed to be'
      : (dropped.length
          ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
          : 'all ' + results.length + ' claimed steps verified'),
  },
} }];
